css:
/* llm-plugin: 스레드 정보 카드 아래, 따로 스크롤되는 명령 안내 상자 (plugins/t3-guide/build_theme.py로 생성) */
[data-thread-details-panel="inline"] { display: flex !important; flex-direction: column; gap: 8px; }
[data-thread-details-panel="inline"] > [data-thread-details-card] { flex: 0 1 auto; min-height: 0; }
[data-thread-details-panel="inline"]::after {
  display: block; flex: none; aspect-ratio: 280 / 384;
  overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; font-size: 0; line-height: 0;
}
[data-thread-details-panel="inline"]::before {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; z-index: -1; pointer-events: none;
  box-sizing: border-box; aspect-ratio: 280 / 384;
  background: var(--popover); border: 1px solid color-mix(in srgb, var(--contrast-foreground) 10%, transparent);
  border-radius: 1rem;
}
.dark [data-thread-details-panel="inline"]::after { content: url("data:image/svg+xml;base64,"); }
:root:not(.dark) [data-thread-details-panel="inline"]::after { content: url("data:image/svg+xml;base64,"); }
